function extractSpreadsheetId(url) {
  const match = String(url || '').match(/\/d\/([a-zA-Z0-9_-]+)/);
  return match ? match[1] : '';
}

const supportedParsers = new Set(['column_villas_month_tabs']);

return $input.all().map((item) => {
  const spreadsheetId = item.json.spreadsheet_id || extractSpreadsheetId(item.json.url);
  const parserType = item.json.parser_type || 'column_villas_month_tabs';
  const parserConfig = item.json.parser_config || {};
  return {
    json: {
      ...item.json,
      spreadsheet_id: spreadsheetId,
      parser_type: parserType,
      parser_config: parserConfig,
      parser_supported: supportedParsers.has(parserType),
      parser_error: supportedParsers.has(parserType) ? '' : `Unsupported parser_type: ${parserType}`,
      metadata_url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`,
      request_url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`,
      color_mapping: item.json.color_mapping || {}
    }
  };
});

const REVIEW_CONFIDENCE = 0.8;
const TODAY = new Date();
TODAY.setHours(0, 0, 0, 0);

function sql(s) {
  return String(s ?? '').replace(/'/g, "''");
}
function slug(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/đ/g, 'd')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80) || 'unit';
}
function hash(s) {
  let h = 2166136261;
  for (let i = 0; i < String(s).length; i++) {
    h ^= String(s).charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}
function bgToHex(bg) {
  if (!bg) return null;
  const r = Math.round((bg.red ?? 0) * 255);
  const g = Math.round((bg.green ?? 0) * 255);
  const b = Math.round((bg.blue ?? 0) * 255);
  if (r === 255 && g === 255 && b === 255) return null;
  return '#' + [r, g, b].map((x) => x.toString(16).padStart(2, '0')).join('');
}
function isRed(hex) {
  if (!hex) return false;
  const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
  return r > 180 && g < 120 && b < 120;
}
function isGreen(hex) {
  if (!hex) return false;
  const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
  return g > 150 && r < 170 && b < 170;
}
function isYellow(hex) {
  if (!hex) return false;
  const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
  return r > 180 && g > 140 && b < 120;
}
function text(v) {
  return String(v ?? '').trim();
}
function normText(v) {
  return text(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/đ/g, 'd');
}
function parsePrice(raw) {
  const s = normText(raw).replace(/\s+/g, '');
  if (!s) return null;
  const tr = s.match(/(\d+(?:[.,]\d+)?)(?:tr|trieu)/);
  if (tr) return Math.round(Number(tr[1].replace(',', '.')) * 1000000);
  const trCompact = s.match(/(\d+)tr(\d+)/);
  if (trCompact) return Number(trCompact[1]) * 1000000 + Number(trCompact[2].padEnd(3, '0')) * 1000;
  const nums = s.match(/\d[\d.,]{4,}/g);
  if (!nums) return null;
  const parsed = nums
    .map((n) => Number(n.replace(/[.,]/g, '')))
    .filter((n) => Number.isFinite(n) && n >= 100000);
  if (!parsed.length) return null;
  return Math.min(...parsed);
}
function parseCapacity(headerText) {
  const s = normText(headerText);
  let standard = null, max = null;
  const range = s.match(/(\d+)\s*[-–]\s*(\d+)\s*(pax|khach|nguoi|nl)/);
  if (range) {
    standard = Number(range[1]);
    max = Number(range[2]);
  }
  const single = s.match(/(\d+)\s*(pax|khach|nguoi|nl)/);
  if (!standard && single) {
    standard = Number(single[1]);
    max = Number(single[1]);
  }
  const plusChild = s.match(/(\d+)\s*nl\s*\+\s*(\d+)\s*te/);
  if (plusChild) {
    standard = Number(plusChild[1]);
    max = Number(plusChild[1]) + Number(plusChild[2]);
  }
  return { standard, max };
}
function parseDate(raw, tabTitle) {
  const s = text(raw);
  const m = s.match(/^(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](\d{2,4}))?$/);
  if (!m) return null;
  const dd = Number(m[1]);
  const mm = Number(m[2]);
  let year = m[3] ? Number(m[3]) : null;
  if (year && year < 100) year += 2000;
  if (!year) {
    const yInTab = String(tabTitle || '').match(/20\d{2}/);
    year = yInTab ? Number(yInTab[0]) : TODAY.getFullYear();
  }
  const d = new Date(year, mm - 1, dd);
  if (Number.isNaN(d.getTime())) return null;
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
function firstUrl(s) {
  const value = String(s || '').trim();
  const parts = value.split(/\s+/);
  return parts.find((p) => /^https?:\/\//i.test(p) && /(maps\.app\.goo\.gl|google\.[^/]*\/maps|goo\.gl\/maps)/i.test(p)) || '';
}
function normName(s) {
  return normText(s).replace(/[^a-z0-9]+/g, '');
}
function bestInfoFor(propertyName, infoRows) {
  const np = normName(propertyName);
  let best = null;
  let bestLen = 0;
  for (const info of infoRows) {
    const ni = normName(info.name);
    if (!ni) continue;
    if ((np.includes(ni) || ni.includes(np)) && ni.length > bestLen) {
      best = info;
      bestLen = ni.length;
    }
  }
  return best;
}
function parseInfoRows(spreadsheet) {
  const out = [];
  for (const tab of spreadsheet.sheets || []) {
    const tabTitle = tab.properties?.title || '';
    const rows = getRows(tab);
    let col = null;
    for (const row of rows) {
      const cells = row.map((c) => normText(c.value));
      const isHeader = cells.some((c) => c.startsWith('ten')) && cells.some((c) => c.includes('dia chi') || c.includes('dinh vi') || c.includes('thong tin'));
      if (isHeader) {
        const find = (keys) => cells.findIndex((c) => keys.some((k) => c.includes(k)));
        col = {
          name: find(['ten']),
          desc: find(['thong tin', 'mo ta']),
          addr: find(['dia chi']),
          map: find(['dinh vi', 'google map', 'maps']),
          note: find(['luu y', 'ghi chu', 'note'])
        };
        continue;
      }
      if (!col || col.name < 0) continue;
      const name = text(row[col.name]?.value);
      if (!name) continue;
      out.push({
        name,
        description: col.desc >= 0 ? text(row[col.desc]?.value) : '',
        address: col.addr >= 0 ? text(row[col.addr]?.value) : '',
        mapUrl: col.map >= 0 ? firstUrl(row[col.map]?.value) : '',
        note: col.note >= 0 ? text(row[col.note]?.value) : '',
        tabTitle
      });
    }
  }
  return out;
}
function shouldSkipPast(iso) {
  const d = new Date(iso + 'T00:00:00');
  return d < TODAY;
}
function getRows(tab) {
  const rowData = tab.data?.[0]?.rowData || [];
  return rowData.map((row) => (row.values || []).map((v) => ({
    value: text(v.formattedValue ?? ''),
    bgHex: bgToHex(v.effectiveFormat?.backgroundColor)
  })));
}
function cell(rows, r, c) {
  return rows[r]?.[c] || { value: '', bgHex: null };
}
function isGenericCapacityName(v) {
  const n = normText(v);
  return /^(\d+\s*[-?]?\s*\d*\s*)?(pax|nl|te|khach|nguoi)/.test(n) || /pax$|nl$|te$/.test(n);
}
function findMonthlyNameRow(rows, firstDateRow) {
  for (let r = 0; r < firstDateRow; r++) {
    const firstCells = [cell(rows, r, 0).value, cell(rows, r, 1).value, cell(rows, r, 2).value].map(normText).join(' ');
    if (/ten\s*(can|villa|phong|nha|homestay)/.test(firstCells)) return r;
  }
  return -1;
}
function detectStatus(rawValue, rawColor, colorMapping) {
  const raw = text(rawValue);
  const s = normText(raw);
  const mapped = rawColor ? colorMapping[String(rawColor).toLowerCase()] : null;

  // VillaOS rule: any colored booking cell means not available by default.
  // Only cells with no background color are treated as available candidates.
  if (/bao\s*tri|sua\s*chua|tam\s*giu|giu\s*cho|hold|blocked|k\s*thu|nghi/.test(s)) return { status: 'blocked', confidence: 0.9 };
  if (rawColor) {
    if (mapped && mapped !== 'available') return { status: mapped, confidence: 0.96 };
    return { status: 'booked', confidence: 0.94 };
  }
  if (/coc|da\s*dat|booked|full|khoa|khach|1\s*doan/.test(s)) return { status: 'booked', confidence: 0.88 };
  if (parsePrice(raw) != null) return { status: 'available', confidence: 0.9 };
  if (!raw) return { status: 'available', confidence: 0.78 };
  return { status: 'unknown', confidence: 0.45 };
}
function extractRulesAndNotes(headerValues, generalNotes) {
  const all = [...headerValues, ...generalNotes].map(text).filter(Boolean);
  const joined = all.join(' | ');
  const n = normText(joined);
  const rules = [];
  if (/khong.*loa|loa\s*keo/.test(n)) rules.push('Không sử dụng loa kéo');
  if (/khong.*karaoke|cam.*karaoke/.test(n)) rules.push('Không karaoke');
  if (/nhan.*thu\s*cung|pet/.test(n)) rules.push('Nhận thú cưng');
  if (/khong.*thu\s*cung/.test(n)) rules.push('Không nhận thú cưng');
  if (/phu\s*thu/.test(n)) rules.push('Có phụ thu');
  const feeNote = all.find((x) => /phụ\s*thu|phu\s*thu|nâng|max|cọc|coc/i.test(x)) || '';
  return { rules: Array.from(new Set(rules)), note: joined, extraFeeNote: feeNote };
}

const responses = $input.all();
const sources = $('Build Ranged Google API Request').all();
const out = [];

for (let i = 0; i < responses.length; i++) {
  const source = sources[i]?.json || {};
  const spreadsheet = responses[i]?.json || {};
  const colorMapping = Object.fromEntries(Object.entries(source.color_mapping || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  const sheetId = source.id;
  const effectiveOwnerId = sheetId;
  const ownerName = source.title || source.owner_name || sheetId;
  const infoRows = parseInfoRows(spreadsheet);
  let rowsParsed = 0;
  let rowsReview = 0;
  const properties = new Map();

  try {
    if (source.skip_sync) {
      out.push({
        json: {
          kind: 'sync',
          sheet_id: sheetId,
          status: 'needs_check',
          rows_parsed: 0,
          rows_review: 0,
          error_sql: sql(source.skip_reason || 'Unsupported parser_type')
        }
      });
      continue;
    }

    for (const tab of spreadsheet.sheets || []) {
      const tabTitle = tab.properties?.title || source.title || 'Sheet';
      if (normText(tabTitle).includes('thong tin')) continue;
      const rows = getRows(tab);
      const maxCols = Math.max(0, ...rows.map((r) => r.length));
      const dateRows = [];
      for (let r = 0; r < rows.length; r++) {
        const first = cell(rows, r, 0).value || cell(rows, r, 1).value;
        const iso = parseDate(first, tabTitle);
        if (iso && !shouldSkipPast(iso)) dateRows.push({ r, iso });
      }
      if (!dateRows.length) continue;

      const firstDateRow = dateRows[0].r;
      const monthlyNameRow = findMonthlyNameRow(rows, firstDateRow);
      const monthlyPropertyIds = new Set();
      if (monthlyNameRow >= 0) {
        for (let c = 1; c < maxCols; c++) {
          const propertyName = text(cell(rows, monthlyNameRow, c).value).slice(0, 120);
          if (!propertyName || isGenericCapacityName(propertyName)) continue;
          const propertyId = effectiveOwnerId + '_' + slug(propertyName);
          if (monthlyPropertyIds.has(propertyId)) continue;
          monthlyPropertyIds.add(propertyId);
          const matchedInfo = bestInfoFor(propertyName, infoRows);
          out.push({
            json: {
              kind: 'property',
              property_id: propertyId,
              owner_id: effectiveOwnerId,
              owner_name: ownerName,
              display_name: propertyName,
              name_sql: sql(propertyName),
              area: '',
              address: matchedInfo?.address || '',
              address_sql: sql(matchedInfo?.address || ''),
              bedrooms: null,
              capacity_standard: null,
              capacity_max: null,
              amenities_json: '[]',
              rules_json: '[]',
              images_json: '[]',
              base_price: null,
              extra_fee_note: matchedInfo?.note || '',
              extra_fee_note_sql: sql(matchedInfo?.note || ''),
              property_note: matchedInfo?.note || '',
              property_note_sql: sql(matchedInfo?.note || ''),
              description: matchedInfo?.description || '',
              description_sql: sql(matchedInfo?.description || ''),
              map_url: matchedInfo?.mapUrl || '',
              map_url_sql: sql(matchedInfo?.mapUrl || ''),
              source_sheet_id: sheetId,
              source_sheet_url: source.url || '',
              source_sheet_url_sql: sql(source.url || '')
            }
          });
        }
      }
      const generalNotes = [];
      for (let r = 0; r < firstDateRow; r++) {
        for (let c = 0; c < maxCols; c++) {
          const v = cell(rows, r, c).value;
          if (/lưu ý|luu y|không|khong|nhận|nhan|phụ thu|phu thu|karaoke|loa kéo|loa keo|thú cưng|thu cung/i.test(v)) generalNotes.push(v);
        }
      }

      for (let c = 1; c < maxCols; c++) {
        const headerValues = [];
        for (let r = 0; r < firstDateRow; r++) {
          const v = cell(rows, r, c).value;
          if (v) headerValues.push(v);
        }
        const hasCalendarCells = dateRows.some(({ r }) => cell(rows, r, c).value || cell(rows, r, c).bgHex);
        if (!hasCalendarCells || headerValues.length === 0) continue;
        const headerText = headerValues.join(' | ');
        const capacity = parseCapacity(headerText);
        const info = extractRulesAndNotes(headerValues, generalNotes);
        const priceFromHeader = parsePrice(headerText);
        const monthlyName = monthlyNameRow >= 0 ? text(cell(rows, monthlyNameRow, c).value) : '';
        const headerName = headerValues.find((v) => /villa|house|homestay|c?n|can|ph?ng|phong/i.test(v) && !isGenericCapacityName(v)) || '';
        const propertyName = text(monthlyName || headerName).slice(0, 120);
        if (!propertyName || isGenericCapacityName(propertyName)) continue;
        const matchedInfo = bestInfoFor(propertyName, infoRows);
        const propertyId = effectiveOwnerId + '_' + slug(propertyName);

        if (!properties.has(propertyId)) {
          properties.set(propertyId, true);
          out.push({
            json: {
              kind: 'property',
              property_id: propertyId,
              owner_id: effectiveOwnerId,
              owner_name: ownerName,
              display_name: propertyName,
              name_sql: sql(propertyName),
              area: '',
              address: matchedInfo?.address || '',
              address_sql: sql(matchedInfo?.address || ''),
              bedrooms: null,
              capacity_standard: capacity.standard,
              capacity_max: capacity.max || capacity.standard,
              amenities_json: '[]',
              rules_json: JSON.stringify(info.rules),
              images_json: '[]',
              base_price: priceFromHeader,
              extra_fee_note: matchedInfo?.note || info.extraFeeNote,
              extra_fee_note_sql: sql(matchedInfo?.note || info.extraFeeNote),
              property_note: info.note,
              property_note_sql: sql(info.note),
              description: matchedInfo?.description || '',
              description_sql: sql(matchedInfo?.description || ''),
              map_url: matchedInfo?.mapUrl || '',
              map_url_sql: sql(matchedInfo?.mapUrl || ''),
              source_sheet_id: sheetId,
              source_sheet_url: source.url || '',
              source_sheet_url_sql: sql(source.url || '')
            }
          });
        }

        for (const { r, iso } of dateRows) {
          const current = cell(rows, r, c);
          const rawValue = current.value;
          const rawColor = current.bgHex;
          const detected = detectStatus(rawValue, rawColor, colorMapping);
          const price = parsePrice(rawValue) ?? priceFromHeader;
          const note = [rawValue && !parsePrice(rawValue) ? rawValue : '', info.extraFeeNote].filter(Boolean).join(' | ');
          rowsParsed++;
          const review = detected.status === 'unknown' || detected.confidence < REVIEW_CONFIDENCE;
          if (review) rowsReview++;
          const base = {
            property_id: propertyId,
            property_name: propertyName,
            date: iso,
            status: detected.status,
            price,
            min_nights: /tối thiểu\s*2|toi thieu\s*2|2\s*đêm|2\s*dem/i.test(info.note) ? 2 : 1,
            note,
            note_sql: sql(note),
            raw_value: rawValue,
            raw_value_sql: sql(rawValue),
            raw_color_hex: rawColor || '#ffffff',
            confidence: detected.confidence,
            source_sheet_id: sheetId,
            source_tab: tabTitle,
            review_id: `rv_${propertyId}_${iso}_${hash(rawValue + rawColor)}`
          };
          out.push({ json: { kind: review ? 'review' : 'availability', ...base } });
        }
      }
    }

    out.push({
      json: {
        kind: 'sync',
        sheet_id: sheetId,
        status: rowsReview > 0 ? 'needs_check' : 'ok',
        rows_parsed: rowsParsed,
        rows_review: rowsReview,
        error_sql: ''
      }
    });
  } catch (error) {
    out.push({
      json: {
        kind: 'sync',
        sheet_id: sheetId,
        status: 'error',
        rows_parsed: rowsParsed,
        rows_review: rowsReview,
        error_sql: sql(error.message || String(error))
      }
    });
  }
}

return out;

function norm(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replaceAll('?', 'd').replaceAll('?', 'd');
}
function isWantedTab(title) {
  const n = norm(title);
  if (!title) return false;
  if (n.includes('thong tin')) return true;
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth() + 1;
  const monthMatch =
    n.match(/(?:thang|t)\s*(\d{1,2})(?:\D*(20\d{2}))?/) ||
    n.match(/\b(\d{1,2})[.\/-](20\d{2})\b/);
  if (!monthMatch) return false;
  const month = Number(monthMatch[1]);
  const year = monthMatch[2] ? Number(monthMatch[2]) : currentYear;
  if (!month || month < 1 || month > 12) return false;
  if (year > currentYear) return true;
  if (year < currentYear) return false;
  return month >= currentMonth;
}
function quoteRange(title) {
  return encodeURIComponent(`'${String(title).replace(/'/g, "''")}'`);
}

const metadataItems = $input.all();
const sourceItems = $('Build Google API Request').all();
const out = [];

for (let i = 0; i < metadataItems.length; i++) {
  const source = sourceItems[i]?.json || {};
  const meta = metadataItems[i]?.json || {};
  if (source.parser_supported === false) {
    out.push({ json: { ...source, skip_sync: true, skip_reason: source.parser_error || 'Unsupported parser_type' } });
    continue;
  }
  const titles = (meta.sheets || []).map((s) => s.properties?.title).filter(Boolean);
  const wanted = titles.filter(isWantedTab);
  const selected = wanted.length ? wanted : titles.filter((t) => norm(t).includes('thong tin')).slice(0, 1);
  const ranges = selected.map((title) => '&ranges=' + quoteRange(title)).join('');
  const fields = encodeURIComponent('spreadsheetId,properties.title,sheets(properties(title),data(rowData(values(formattedValue,effectiveFormat(backgroundColor)))))');
  out.push({
    json: {
      ...source,
      selected_tabs: selected,
      skipped_tabs: titles.filter((t) => !selected.includes(t)),
      request_url: `https://sheets.googleapis.com/v4/spreadsheets/${source.spreadsheet_id}?includeGridData=true&fields=${fields}${ranges}`
    }
  });
}

return out;
